insert into e34_private.affiliate_applications(program_id,status,description,audience,placements,traffic_statement,required_information,introduction,owner_notes,submitted_at) values('google-adsense','under_review','E34 Lore is an independent BMW E34 repair reference and owner community at e34lore.com. We publish original service walkthroughs, source-cited OEM part-number and exploded-diagram references, diagnostic discussions, and owner restoration journals. Our intended audience is BMW E34 owners, restorers and DIY enthusiasts, from beginners to experienced technicians. Planned partner placements are clearly disclosed retailer links beside reviewed part matches and relevant technical content. E34 Lore is newly launched; reliable monthly traffic and sales figures are not yet available. Commercial relationships will not determine technical fitment judgments.','BMW E34 owners, restorers and DIY enthusiasts. This is the intended audience; no audience size, demographics or geographic distribution is claimed.','Clearly disclosed Where to Buy links beside human-reviewed catalog matches. At most two nonintrusive sponsor placements on eligible public pages after owner approval. No display ads in repair steps, diagnosis, the workshop, private garages, account settings or administration.','Newly launched. Reliable monthly visitors, subscribers, referred sales and conversion rates are not yet established. Optional anonymous section-open counters include owner/testing activity and cannot establish unique visitors.','Owner completed customer information directly in Google. Approval and any required certified consent configuration remain external.','I run E34 Lore, an independent BMW E34 technical reference and owner community. I would like to discuss a content-publisher relationship using disclosed, source-reviewed parts links. We preserve technical fitment independently of commercial terms and do not publish unverified retailer matches as replacements. The site is newly launched, so I cannot yet provide reliable monthly audience or sales figures. Please confirm publisher eligibility, approved deep-link rules, feed/image permissions, attribution and payment terms.','Google displayed Review requested, Getting ready, and all setup steps completed on 7 November 2026.',now());
update e34_private.commercial_settings set adsense_status='under_review',adsense_notes='Ownership verified, review requested and payee setup completed by owner on 7 November 2026. No ad script or Auto ads has been deployed.' where id='site';
